-- Migration: Year 2 - Renal/Urinary Pathology MCQ Bank (PART 2: 76-150)
-- Topics: Nephrotic Syndromes
-- Date: 2026-04-24

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Renal/Urinary Pathology', 'renal-urinary-pathology', 3, 2, 50)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- NEPHROTIC SYNDROME BASICS & MINIMAL CHANGE DISEASE (76-90)
    (v_topic_id, '76. The hallmark of Nephrotic Syndrome is?', '["Hematuria and RBC casts", "Proteinuria > 3.5 g/day", "Oliguria and hypertension", "Pyuria and WBC casts"]', 1, 'Nephrotic syndrome is characterized by massive proteinuria (>3.5g/day) leading to hypoalbuminemia, generalized edema, and hyperlipidemia.'),
    (v_topic_id, '77. Why do patients with Nephrotic Syndrome develop hypercoagulability?', '["Loss of Antithrombin III in the urine", "Increased production of Vitamin K", "Loss of Protein C and S only", "Increased platelet aggregation"]', 0, 'The loss of Antithrombin III (a small regulatory protein) in the urine tips the balance toward thrombosis, frequently leading to renal vein thrombosis.'),
    (v_topic_id, '78. Patients with Nephrotic Syndrome are at increased risk of infection primarily due to?', '["Loss of neutrophils in the urine", "Loss of immunoglobulins (IgG) in the urine", "Decreased production of T-cells", "Hypoalbuminemia causing tissue edema"]', 1, 'Loss of immunoglobulins (especially IgG) in the massive proteinuria leaves patients susceptible to infections (especially encapsulated bacteria like Strep pneumoniae).'),
    (v_topic_id, '79. Fatty casts and "oval fat bodies" in the urine are characteristic of?', '["Nephritic Syndrome", "Nephrotic Syndrome", "Acute Tubular Necrosis", "Acute Interstitial Nephritis"]', 1, 'The liver ramps up lipid production to compensate for low albumin. Lipids leak into the urine, taken up by tubular cells (oval fat bodies), and form fatty casts (Maltese cross appearance under polarized light).'),
    (v_topic_id, '80. What is the most common cause of Nephrotic Syndrome in children?', '["Focal Segmental Glomerulosclerosis (FSGS)", "Membranous Nephropathy", "Minimal Change Disease", "Post-Streptococcal GN"]', 2, 'Minimal Change Disease accounts for the vast majority of nephrotic syndrome in children, often triggered by a recent infection or immunization.'),
    (v_topic_id, '81. What does Light Microscopy show in Minimal Change Disease?', '["Glomerulosclerosis", "Thickened capillary loops", "Normal glomeruli", "Crescents"]', 2, 'The glomeruli appear completely normal on Light Microscopy (hence the name "Minimal Change").'),
    (v_topic_id, '82. What is the definitive diagnostic finding in Minimal Change Disease on Electron Microscopy?', '["Subepithelial humps", "Effacement of podocyte foot processes", "Subendothelial deposits", "Basket-weave GBM"]', 1, 'Cytokines cause the podocyte foot processes to flatten (effacement), destroying the charge barrier of the GBM and allowing albumin to leak out.'),
    (v_topic_id, '83. The proteinuria in Minimal Change Disease is described as "selective". This means?', '["Only heavy chain immunoglobulins are lost", "Only albumin is lost, immunoglobulins are spared", "Both albumin and immunoglobulins are lost equally", "Only Bence-Jones proteins are lost"]', 1, 'Because the defect is primarily a loss of the negative charge barrier (not massive structural holes), only smaller, negatively charged proteins like albumin are lost. Larger immunoglobulins stay in the blood.'),
    (v_topic_id, '84. What is the typical treatment and response for Minimal Change Disease?', '["Dialysis, poor response", "Plasmapheresis, variable response", "Corticosteroids, excellent response", "ACE inhibitors, moderate response"]', 2, 'Minimal Change Disease has an excellent prognosis and typically responds rapidly to corticosteroid therapy.'),
    (v_topic_id, '85. Minimal Change Disease is strongly associated with which malignancy?', '["Renal Cell Carcinoma", "Hodgkin Lymphoma", "Multiple Myeloma", "Lung Cancer"]', 1, 'Hodgkin Lymphoma involves massive cytokine production by Reed-Sternberg cells, which can trigger podocyte effacement and secondary Minimal Change Disease.'),
    (v_topic_id, '86. Immunofluorescence in Minimal Change Disease is typically?', '["Linear IgG", "Granular IgA", "Negative", "Full house"]', 2, 'MCD is entirely cytokine-mediated, so there are NO immune complexes. IF is negative.'),
    (v_topic_id, '87. If a child with presumed Minimal Change Disease does NOT respond to steroids, what is the most likely alternative diagnosis?', '["Membranous Nephropathy", "Focal Segmental Glomerulosclerosis (FSGS)", "IgA Nephropathy", "PSGN"]', 1, 'Steroid-resistant nephrotic syndrome in a child is highly suspicious for FSGS, requiring a renal biopsy.'),
    (v_topic_id, '88. The generalized edema in nephrotic syndrome begins classically in which location?', '["Pulmonary edema", "Ascites", "Periorbital edema", "Pedal edema"]', 2, 'Due to low oncotic pressure, fluid accumulates in areas with low tissue tension, such as the loose connective tissue around the eyes (periorbital edema), especially in the morning.'),
    (v_topic_id, '89. Why do patients with Nephrotic Syndrome have hypercholesterolemia?', '["Decreased breakdown of LDL", "Hepatic synthesis of lipids increases to compensate for low serum oncotic pressure", "Loss of HDL in the urine", "Increased dietary absorption of fats"]', 1, 'The liver senses the low albumin/oncotic pressure and ramps up production of all proteins and lipoproteins, causing hyperlipidemia.'),
    (v_topic_id, '90. A patient with Nephrotic Syndrome presents with acute flank pain, hematuria, and left-sided varicocele. What happened?', '["Rupture of a renal cyst", "Kidney stone", "Renal Vein Thrombosis", "Aortic dissection"]', 2, 'Loss of Antithrombin III causes hypercoagulability. Renal vein thrombosis blocks outflow, causing flank pain and preventing the left gonadal vein from draining (left varicocele).'),

    -- FOCAL SEGMENTAL GLOMERULOSCLEROSIS (FSGS) (91-105)
    (v_topic_id, '91. What is the most common cause of Nephrotic Syndrome in Hispanic and African American adults?', '["Minimal Change Disease", "Membranous Nephropathy", "Focal Segmental Glomerulosclerosis (FSGS)", "Diabetic Nephropathy"]', 2, 'FSGS is the leading cause of primary nephrotic syndrome in adults, especially in Hispanic and African American populations.'),
    (v_topic_id, '92. The name "Focal Segmental" implies that the sclerosis involves?', '["All glomeruli entirely", "Only some glomeruli, and only a portion of the affected glomerulus", "All glomeruli, but only a portion of each", "Only some glomeruli entirely"]', 1, 'Focal = some glomeruli (<50%). Segmental = only a portion of the tuft in the affected glomeruli. Sclerosis = pink, dense collagen deposition.'),
    (v_topic_id, '93. Secondary FSGS is highly associated with which viral infection?', '["Hepatitis B", "Hepatitis C", "HIV", "Epstein-Barr Virus"]', 2, 'HIV-associated nephropathy is a collapsing variant of FSGS. FSGS is also associated with heroin use and sickle cell disease.'),
    (v_topic_id, '94. What does Light Microscopy show in FSGS?', '["Normal glomeruli", "Thickened capillary loops", "Segmental sclerosis and hyalinosis", "Crescents"]', 2, 'Sclerosis (collagen) and hyalinosis (trapped proteins/lipids) occur in segments of some glomeruli.'),
    (v_topic_id, '95. What does Electron Microscopy show in FSGS?', '["Subepithelial spikes", "Effacement of podocyte foot processes", "Subendothelial deposits", "Basket-weave GBM"]', 1, 'Like MCD, EM in FSGS shows podocyte effacement. FSGS can be thought of as a more severe, progressive form of MCD where the podocytes eventually die, leading to sclerosis.'),
    (v_topic_id, '96. What does Immunofluorescence show in FSGS?', '["Negative, but may have non-specific focal trapping of IgM and C3 in sclerotic areas", "Granular IgG", "Linear IgG", "IgA in mesangium"]', 0, 'IF is generally negative for primary immune complexes, but large molecules like IgM and C3 can get nonspecifically trapped in the sclerotic areas.'),
    (v_topic_id, '97. The proteinuria in FSGS is described as?', '["Selective", "Non-selective", "Bence-Jones", "Microalbuminuria only"]', 1, 'Unlike MCD, the glomerular damage in FSGS is structural, allowing both albumin and larger immunoglobulins to leak out (non-selective proteinuria).'),
    (v_topic_id, '98. How does FSGS respond to corticosteroid therapy?', '["Excellent response, rarely progresses", "Poor response, progresses to chronic renal failure", "Immediate cure", "Worsens the condition"]', 1, 'Unlike MCD, FSGS is typically steroid-resistant and progresses to End-Stage Renal Disease (ESRD) requiring dialysis or transplant.'),
    (v_topic_id, '99. "Collapsing glomerulopathy" is a highly aggressive variant of FSGS strongly associated with?', '["Heroin", "Obesity", "HIV infection", "Sickle Cell Trait"]', 2, 'HIV-associated nephropathy (HIVAN) classically presents as collapsing FSGS with massive proteinuria and rapid progression to ESRD.'),
    (v_topic_id, '100. Massive obesity and single-kidney status (e.g., post-nephrectomy) are associated with which secondary glomerular disease?', '["Membranous Nephropathy", "Minimal Change Disease", "Adaptive FSGS", "PSGN"]', 2, 'Loss of nephron mass or massive body mass causes hyperfiltration injury (hemodynamic stress) in the remaining glomeruli, leading to adaptive secondary FSGS.'),
    (v_topic_id, '101. Is the hematuria in FSGS macroscopic (gross) or microscopic?', '["Gross", "Microscopic", "No hematuria", "It is exclusively a nephritic syndrome"]', 1, 'While primarily nephrotic, FSGS can present with microscopic hematuria and hypertension, blurring the lines slightly between nephrotic and nephritic.'),
    (v_topic_id, '102. Does FSGS recur in transplanted kidneys?', '["Never", "Rarely", "Often (up to 30-50% of cases)", "Only in HIV positive patients"]', 2, 'Primary FSGS has a high recurrence rate in allografts, suggesting a circulating permeability factor is responsible for the disease.'),
    (v_topic_id, '103. Sickle cell disease is associated with which two renal pathologies?', '["FSGS and Renal Papillary Necrosis", "Minimal Change Disease and PSGN", "Membranous Nephropathy and Stones", "Goodpasture and Alport"]', 0, 'The sickling in the vasa recta causes renal papillary necrosis, and the chronic hyperfiltration leads to secondary FSGS.'),
    (v_topic_id, '104. Which gene mutation is associated with a familial form of FSGS?', '["PKD1", "COL4A5", "NPHS2 (Podocin) or APOL1", "RET"]', 2, 'Mutations in podocyte proteins (Podocin, Nephrin) or the APOL1 gene (which confers trypanosome resistance but increases kidney disease risk in African Americans) cause FSGS.'),
    (v_topic_id, '105. A biopsy is taken from a patient with heavy proteinuria. Only 10 glomeruli are captured, and all look normal. If the patient has FSGS, why might it be missed?', '["FSGS cannot be seen on light microscopy", "Sampling error: the biopsy missed the focal lesions", "FSGS only affects tubules", "The patient has Minimal Change Disease"]', 1, 'Because FSGS is focal (affecting only some glomeruli, often starting deep in the juxtamedullary region), a superficial biopsy might miss the lesions completely.'),

    -- MEMBRANOUS NEPHROPATHY (106-120)
    (v_topic_id, '106. What is the most common cause of primary Nephrotic Syndrome in Caucasian adults?', '["FSGS", "Minimal Change Disease", "Membranous Nephropathy", "Diabetic Nephropathy"]', 2, 'Membranous Nephropathy is the most common primary cause in Caucasian adults, though FSGS is increasing overall.'),
    (v_topic_id, '107. Primary Membranous Nephropathy is most commonly caused by autoantibodies against?', '["The GBM (Type IV Collagen)", "Phospholipase A2 Receptor (PLA2R)", "IgA", "ANCA"]', 1, 'Over 70% of primary cases are associated with anti-PLA2R antibodies, which attack the podocytes.'),
    (v_topic_id, '108. What is the hallmark finding on Light Microscopy in Membranous Nephropathy?', '["Diffuse thickening of the glomerular basement membrane", "Crescents", "Mesangial proliferation", "Segmental sclerosis"]', 0, 'The massive deposition of immune complexes causes the basement membrane to thicken diffusely, without significant cellular proliferation.'),
    (v_topic_id, '109. What does Immunofluorescence show in Membranous Nephropathy?', '["Linear IgG", "Granular IgG and C3", "Negative", "Mesangial IgA"]', 1, 'The immune complexes deposit subepithelially, creating a diffuse granular pattern on IF.'),
    (v_topic_id, '110. What is the classic finding on Electron Microscopy in Membranous Nephropathy?', '["Subendothelial humps", "Subepithelial ''spike and dome'' appearance", "Basket-weave GBM", "Normal GBM"]', 1, 'Immune complexes deposit subepithelially (the "dome"). The podocytes respond by laying down new basement membrane between the complexes, creating "spikes".'),
    (v_topic_id, '111. Secondary Membranous Nephropathy is strongly associated with?', '["Solid tumors, Hepatitis B, SLE, and drugs (e.g., NSAIDs, Penicillamine)", "HIV and Heroin", "Streptococcal infections", "Hodgkin Lymphoma"]', 0, 'Always screen patients with Membranous Nephropathy for solid tumors (lung, colon, breast) and Hepatitis B, as it is often a paraneoplastic or secondary manifestation.'),
    (v_topic_id, '112. When SLE causes a nephrotic syndrome, which pattern is most common?', '["Class IV: Diffuse Proliferative", "Class V: Membranous Nephropathy", "Minimal Change Disease", "FSGS"]', 1, 'While Class IV (DPGN) is the most common nephritic lupus lesion, Class V (Membranous Nephropathy) is the classic nephrotic lupus lesion.'),
    (v_topic_id, '113. How does Membranous Nephropathy respond to corticosteroids?', '["Excellent response", "Poor response, often slowly progresses to chronic renal failure", "Immediate cure", "Responds only to plasmapheresis"]', 1, 'Unlike Minimal Change Disease, Membranous Nephropathy typically has a poor response to steroids alone and slowly progresses over years.'),
    (v_topic_id, '114. Which nephrotic syndrome has the highest risk of Renal Vein Thrombosis?', '["Minimal Change Disease", "FSGS", "Membranous Nephropathy", "Diabetic Nephropathy"]', 2, 'While all nephrotic syndromes carry a clotting risk, Membranous Nephropathy has the highest incidence of renal vein thrombosis.'),
    (v_topic_id, '115. A 55-year-old male presents with massive proteinuria and left flank pain. Workup reveals a lung mass and a left varicocele. What is the diagnosis?', '["Goodpasture Syndrome", "Secondary Membranous Nephropathy complicated by RVT", "Renal Cell Carcinoma", "Wegener Granulomatosis"]', 1, 'The lung cancer caused paraneoplastic Membranous Nephropathy. The nephrotic state led to Antithrombin III loss, causing Renal Vein Thrombosis (flank pain, varicocele).'),
    (v_topic_id, '116. Are there hypercellular changes (e.g., proliferating mesangial cells or neutrophils) in Membranous Nephropathy?', '["Yes, marked proliferation", "No, it is a non-proliferative disease", "Yes, but only crescents", "Yes, endothelial cells proliferate"]', 1, 'It is characterized purely by thickened basement membranes ("membranous") without an influx of inflammatory cells ("non-proliferative").'),
    (v_topic_id, '117. What happens to the podocytes in Membranous Nephropathy?', '["They are completely spared", "They undergo effacement of foot processes", "They proliferate to form crescents", "They detach and excrete in urine"]', 1, 'As with all nephrotic syndromes, the podocyte foot processes are effaced due to the underlying damage (in this case, from subepithelial immune complexes).'),
    (v_topic_id, '118. Which drug is notorious for causing Membranous Nephropathy?', '["Penicillin", "NSAIDs", "Aminoglycosides", "Lithium"]', 1, 'NSAIDs, Penicillamine, and gold salts are classic drug-induced causes of Membranous Nephropathy.'),
    (v_topic_id, '119. A patient with Membranous Nephropathy has a positive ANA and anti-dsDNA. What is the underlying cause?', '["Hepatitis B", "Systemic Lupus Erythematosus", "Primary anti-PLA2R disease", "Colon cancer"]', 1, 'The presence of lupus autoantibodies confirms this is Class V Lupus Nephritis.'),
    (v_topic_id, '120. Spontaneous remission occurs in what percentage of patients with primary Membranous Nephropathy?', '["0%", "About 30%", "100%", "90%"]', 1, 'The Rule of Thirds: ~1/3 spontaneously remit, ~1/3 remain stable with proteinuria, and ~1/3 progress to ESRD.'),

    -- DIABETIC NEPHROPATHY (121-135)
    (v_topic_id, '121. What is the most common cause of End-Stage Renal Disease (ESRD) in the United States?', '["Hypertension", "Diabetic Nephropathy", "Polycystic Kidney Disease", "FSGS"]', 1, 'Diabetes Mellitus is the #1 cause of ESRD, followed closely by Hypertension.'),
    (v_topic_id, '122. What is the earliest clinical manifestation of Diabetic Nephropathy?', '["Gross hematuria", "Microalbuminuria", "Massive proteinuria", "Elevated Creatinine"]', 1, 'Microalbuminuria (30-300 mg/day), which is not detected by a standard urine dipstick, is the first sign of glomerular damage.'),
    (v_topic_id, '123. The pathogenesis of Diabetic Nephropathy involves non-enzymatic glycosylation of?', '["The Glomerular Basement Membrane and Efferent Arteriole", "The Afferent Arteriole only", "The proximal tubules", "The collecting duct"]', 0, 'Glycosylation of the GBM increases permeability. Glycosylation of the efferent arteriole causes hyaline arteriolosclerosis.'),
    (v_topic_id, '124. Why does non-enzymatic glycosylation of the efferent arteriole cause renal damage?', '["It blocks blood flow to the glomerulus", "It stiffens and narrows the efferent arteriole, increasing glomerular hydrostatic pressure and causing hyperfiltration injury", "It causes massive bleeding", "It decreases renin release"]', 1, 'Narrowing the exit (efferent) while the entrance (afferent) remains open causes high pressure in the glomerulus. This hyperfiltration leads to microalbuminuria and eventually sclerosis.'),
    (v_topic_id, '125. Which medication class is specifically indicated to slow the progression of Diabetic Nephropathy?', '["Beta-blockers", "ACE inhibitors or ARBs", "Calcium channel blockers", "Diuretics"]', 1, 'ACE inhibitors block Angiotensin II, which normally constricts the efferent arteriole. By dilating the efferent arteriole, ACEi reduce the hyperfiltration pressure, protecting the glomerulus.'),
    (v_topic_id, '126. What is the classic finding on Light Microscopy in advanced Diabetic Nephropathy?', '["Subepithelial humps", "Crescents", "Kimmelstiel-Wilson nodules", "Tram-tracks"]', 2, 'Kimmelstiel-Wilson nodules are eosinophilic, nodular accumulations of mesangial matrix located at the periphery of the glomerulus. Pathognomonic for diabetic nephropathy.'),
    (v_topic_id, '127. Before the formation of nodules, what is the most common structural change in Diabetic Nephropathy?', '["Diffuse mesangial sclerosis and GBM thickening", "Crescent formation", "Endothelial proliferation", "Tubular atrophy"]', 0, 'Diffuse thickening of the GBM and diffuse expansion of the mesangium occurs years before the formation of discrete nodules.'),
    (v_topic_id, '128. Is the proteinuria in Diabetic Nephropathy considered nephritic or nephrotic?', '["Nephritic", "Nephrotic", "Neither", "Both"]', 1, 'It begins as microalbuminuria but progressively worsens to massive, nephrotic-range proteinuria over years.'),
    (v_topic_id, '129. Why are diabetic patients more prone to Renal Papillary Necrosis?', '["High glucose is directly toxic to papillae", "Hyaline arteriolosclerosis compromises the delicate blood supply to the medullary papillae", "Massive immune complex deposition", "Increased ureteral pressure"]', 1, 'The renal papillae are highly vulnerable to ischemia. Vascular compromise from diabetes (along with NSAIDs, sickle cell, and pyelonephritis) causes them to slough off.'),
    (v_topic_id, '130. A patient with long-standing diabetes presents with sudden onset of gross hematuria and flank pain. Urine shows necrotic tissue fragments. Diagnosis?', '["Diabetic Nephropathy progressing to ESRD", "Renal Papillary Necrosis", "Renal Cell Carcinoma", "Acute Cystitis"]', 1, 'The sloughing of the necrotic papillae causes gross hematuria and flank pain (often mimicking a kidney stone).'),
    (v_topic_id, '131. Type IV Renal Tubular Acidosis (Hyporeninemic Hypoaldosteronism) is commonly seen in diabetics. What is the classic electrolyte finding?', '["Hypokalemia", "Hyperkalemia and normal anion gap metabolic acidosis", "Hypernatremia", "High anion gap metabolic acidosis"]', 1, 'Damage to the juxtaglomerular apparatus decreases renin release, leading to low aldosterone, causing K+ retention (hyperkalemia) and H+ retention (acidosis).'),
    (v_topic_id, '132. What is the mechanism of ACE inhibitor-induced acute renal failure in a diabetic patient with bilateral renal artery stenosis?', '["Direct tubular toxicity", "Loss of Angiotensin II removes the efferent constriction needed to maintain GFR in the face of low afferent flow", "Allergic interstitial nephritis", "Massive proteinuria"]', 1, 'If renal blood flow is already blocked by stenosis, the kidney relies on AT-II to constrict the efferent arteriole to maintain GFR. Blocking this drops GFR to zero.'),
    (v_topic_id, '133. SGLT2 inhibitors (e.g., Empagliflozin) protect the diabetic kidney by?', '["Decreasing glucose reabsorption in the proximal tubule, which increases sodium delivery to the macula densa, restoring tubuloglomerular feedback and reducing hyperfiltration", "Dilating the efferent arteriole directly", "Inhibiting mesangial matrix production", "Directly repairing podocytes"]', 0, 'By restoring Na+ delivery to the macula densa, SGLT2 inhibitors cause afferent arteriole constriction, reducing the harmful hyperfiltration pressure.'),
    (v_topic_id, '134. Which urinary finding would definitively rule OUT Diabetic Nephropathy as the sole cause of renal failure in a diabetic patient?', '["Hyaline casts", "Oval fat bodies", "RBC casts", "Microalbuminuria"]', 2, 'RBC casts indicate a nephritic syndrome (glomerular inflammation/bleeding). Diabetic nephropathy is a non-inflammatory nephrotic process. If RBC casts are present, another disease (e.g., PSGN, IgA) is superimposed.'),
    (v_topic_id, '135. Nodular glomerulosclerosis is the classic lesion, but the most COMMON lesion in diabetic nephropathy is?', '["Diffuse glomerulosclerosis", "Crescentic GN", "Minimal Change Disease", "FSGS"]', 0, 'Diffuse mesangial expansion/sclerosis is present in almost all patients with diabetic nephropathy, while KW nodules only form in a subset (though they are pathognomonic).'),

    -- SYSTEMIC AMYLOIDOSIS (136-150)
    (v_topic_id, '136. Which organ is the most commonly involved organ in Systemic Amyloidosis?', '["Heart", "Liver", "Kidney", "Brain"]', 2, 'The kidney is the most commonly involved organ, presenting with nephrotic syndrome.'),
    (v_topic_id, '137. What type of amyloid deposits in AL Amyloidosis (Primary amyloidosis)?', '["Mutated Transthyretin", "Serum Amyloid A (SAA)", "Ig Light Chains", "Beta-amyloid"]', 2, 'AL amyloid is derived from monoclonal immunoglobulin Light chains, usually associated with Multiple Myeloma or plasma cell dyscrasias.'),
    (v_topic_id, '138. What type of amyloid deposits in AA Amyloidosis (Secondary amyloidosis)?', '["Ig Light Chains", "Serum Amyloid A (SAA)", "Beta-2 microglobulin", "Amylin"]', 1, 'AA amyloid is derived from SAA, an acute phase reactant. It occurs secondary to chronic inflammatory states (e.g., Rheumatoid Arthritis, Tuberculosis, Inflammatory Bowel Disease, Familial Mediterranean Fever).'),
    (v_topic_id, '139. Where does the amyloid specifically deposit in the kidney?', '["Inside the tubular cells", "In the mesangium, resulting in nephrotic syndrome", "In the collecting ducts", "In the renal pelvis"]', 1, 'Amyloid deposits in the mesangium and capillary walls, disrupting the filtration barrier and causing massive proteinuria.'),
    (v_topic_id, '140. What is the diagnostic histological stain for Amyloidosis?', '["Silver stain", "Congo Red stain", "PAS stain", "Trichrome stain"]', 1, 'Congo Red staining is diagnostic for amyloid.'),
    (v_topic_id, '141. How does amyloid appear under polarized light microscopy after Congo Red staining?', '["Apple-green birefringence", "Maltese cross appearance", "Blue fluorescence", "Red-orange birefringence"]', 0, 'The beta-pleated sheet structure of amyloid creates apple-green birefringence under polarized light.'),
    (v_topic_id, '142. A patient with a history of Rheumatoid Arthritis presents with massive proteinuria and enlarged kidneys. Diagnosis?', '["Secondary (AA) Amyloidosis", "Primary (AL) Amyloidosis", "Membranous Nephropathy", "Lupus Nephritis"]', 0, 'Chronic inflammation from RA leads to SAA overproduction and AA amyloidosis in the kidneys.'),
    (v_topic_id, '143. A patient with bone pain, hypercalcemia, and lytic bone lesions develops nephrotic syndrome. Biopsy shows apple-green birefringence. Diagnosis?', '["Multiple Myeloma causing AL Amyloidosis", "Metastatic prostate cancer", "Primary Hyperparathyroidism", "Paget Disease"]', 0, 'Multiple Myeloma produces excess light chains, which deposit as AL amyloid in the kidneys.'),
    (v_topic_id, '144. Dialysis-associated amyloidosis is caused by deposition of which protein?', '["Serum Amyloid A", "Beta-2 microglobulin", "Transthyretin", "Light chains"]', 1, 'Beta-2 microglobulin is not effectively cleared by dialysis machines. It accumulates over years and deposits as amyloid, often in joints (causing carpal tunnel syndrome) and bone.'),
    (v_topic_id, '145. How do the kidneys typically appear grossly in advanced Systemic Amyloidosis?', '["Small and shrunken", "Large, pale, and waxy", "Cystic and hemorrhagic", "Normal"]', 1, 'The massive extracellular deposition of amyloid proteins causes the kidneys (and liver/spleen) to become enlarged, pale, and firm/waxy.'),
    (v_topic_id, '146. A patient with Familial Mediterranean Fever is at high risk for?', '["AL Amyloidosis", "AA Amyloidosis", "Dialysis Amyloidosis", "Senile Amyloidosis"]', 1, 'FMF is a genetic autoinflammatory disorder characterized by recurrent fevers and serositis. The chronic inflammation leads to AA amyloidosis (prevented by Colchicine).'),
    (v_topic_id, '147. Does amyloidosis cause a nephritic or nephrotic syndrome?', '["Pure nephritic", "Pure nephrotic", "Isolated hematuria", "Rapidly progressive renal failure"]', 1, 'It disrupts the filtration barrier structurally, leading to heavy, non-selective proteinuria (Nephrotic Syndrome) without significant inflammation (no RBC casts).'),
    (v_topic_id, '148. What does Electron Microscopy show in Amyloidosis?', '["Subepithelial humps", "Thickened GBM with haphazardly arranged, non-branching fibrils", "Subendothelial deposits", "Basket-weave appearance"]', 1, 'EM reveals the characteristic 7-10 nm non-branching fibrils of amyloid.'),
    (v_topic_id, '149. The prognosis for renal amyloidosis is?', '["Excellent, reverses with steroids", "Variable, resolves spontaneously", "Poor, typically progresses to End-Stage Renal Disease", "Benign, causes only asymptomatic proteinuria"]', 2, 'The deposited amyloid cannot be easily removed by the body. It progressively destroys the glomeruli, leading to ESRD. Treatment focuses on stopping the underlying production (e.g., treating the Myeloma or RA).'),
    (v_topic_id, '150. A biopsy is planned to confirm systemic amyloidosis. What is a common, minimally invasive site to biopsy first?', '["Brain", "Kidney", "Abdominal fat pad or rectum", "Heart"]', 2, 'An abdominal fat pad aspirate or rectal mucosal biopsy is safer than a renal/cardiac biopsy and often yields a positive Congo Red stain due to systemic deposition.');

    RAISE NOTICE 'SUCCESS: Renal Pathology MCQs Part 2 (76-150) registered.';
END $$;

COMMIT;
